using System.ComponentModel.DataAnnotations;
using FIXIT.Domain.Entities;
namespace FIXIT.API.Contracts;
public sealed record RegisterRequest([Required,EmailAddress] string Email,[Required,MinLength(12)] string Password,[Required,StringLength(80)] string FirstName,[Required,StringLength(80)] string LastName,[Required,Phone] string PhoneNumber,string Role="Customer");
public sealed record LoginRequest([Required,EmailAddress] string Email,[Required] string Password);
public sealed record AddressRequest([Required,StringLength(200)] string Street,[Required,StringLength(100)] string Barangay,[Required,StringLength(100)] string CityMunicipality,[Required,StringLength(100)] string Province,[Required,StringLength(100)] string Region,string? Landmark,bool IsDefault=false);
public sealed record BookingRequest([Range(1,int.MaxValue)] int ServiceId,[Range(1,int.MaxValue)] int AddressId,[Required,StringLength(2000)] string ProblemDescription,DateTimeOffset ScheduledAt,PaymentMethod PaymentMethod);
public sealed record StatusRequest(BookingStatus Status,[StringLength(500)] string? Note);
public sealed record TechnicianApplicationRequest([Required,MinLength(1)] int[] ServiceIds,[Required,MinLength(1)] int[] CoverageAreaIds,[StringLength(1000)] string? OtherSkills);
public sealed record AdditionalWorkRequestBody([Required,StringLength(800)] string Description,[Range(1,100000)] decimal Amount);
public sealed record ReviewRequest([Range(1,5)] int Rating,[StringLength(1200)] string? Comment);
public sealed record TicketRequest([Required,StringLength(180)] string Subject,[Required,StringLength(3000)] string Message);
public sealed record DisputeRequest([Required,StringLength(2000)] string Description);
public sealed record ServiceUpsert([Required,StringLength(100)] string Name,[Required,StringLength(2000)] string Description,[Range(0,100000)] decimal BasePrice,bool IsActive=true);
public sealed record AssignmentRequest([Required] string TechnicianId,[Required,StringLength(300)] string Reason);
public sealed record ReviewDecisionRequest(bool Visible,[StringLength(500)] string? Reason);
public sealed record UserStatusRequest(bool Active,[Required,StringLength(500)] string Reason);
public sealed record AdministratorCreateRequest([Required,EmailAddress] string Email,[Required,MinLength(12)] string Password,[Required,StringLength(80)] string FirstName,[Required,StringLength(80)] string LastName);
public sealed record TechnicianDecisionRequest(bool Approve,[Required,StringLength(500)] string Reason);
public sealed record AreaUpsert([Required,StringLength(120)] string CityMunicipality,[Required,StringLength(120)] string Province,bool IsActive=true);
public sealed record ProfileUpdate([Required,StringLength(80)] string FirstName,[Required,StringLength(80)] string LastName,[Required,Phone] string PhoneNumber);
public sealed record AvailabilitySlotRequest([Range(0,6)] int DayOfWeek,TimeOnly StartTime,TimeOnly EndTime,bool IsAvailable=true);
public sealed record JobDeclineRequest([StringLength(300)] string? Reason);
public sealed record WorkReportRequest([Required,StringLength(4000)] string CompletionNotes,[StringLength(2000)] string? PartsUsed);
public sealed record RefundDecisionRequest(bool Approve,[Required,StringLength(500)] string Reason);
public sealed record DisputeResolutionRequest([Required,StringLength(2000)] string Resolution,bool Resolved=true);
public sealed record VerificationDecisionRequest(bool Approve,[Required,StringLength(500)] string Reason);
public sealed record ChangePasswordRequest([Required] string CurrentPassword,[Required,MinLength(12)] string NewPassword);
public sealed record PlatformSettingsUpdate([Range(0,50)] decimal PlatformFeePercent,[Range(0,168)] decimal CancellationHours);
